<section class="section-heading"><div><span class="section-kicker">YOUR VISUAL LIBRARY</span><h2>Set the scene</h2><p>Original system artwork and your private uploads, kept in separate storage.</p></div><label class="filter-label">Category<select id="artwork-filter"><option value="all">All categories</option><?php foreach(ag_sd_artwork_library() as $id=>$art):?><option value="<?=ag_h($id)?>"><?=ag_h($art['name'])?></option><?php endforeach ?><option value="uploads">My uploads</option></select></label></section>
<?php $artCard=function($id,$url,$name,$uploaded=false)use($hidden,$state){$selected=array();foreach(ag_sd_scopes() as $scope=>$label){$t=ag_sd_active_theme($state,$scope);if(($uploaded?($t['styles']['background'] ?? ''):($t['styles']['artwork'] ?? ''))===$id)$selected[]=$label;}?><article class="art-card studio-panel" data-art-category="<?=ag_h($uploaded?'uploads':$id)?>"><button class="art-preview-button preview-design" type="button" data-url="/Other/site-artwork-preview.php?<?=$uploaded?'upload':'artwork'?>=<?=ag_h($id)?>"><img loading="lazy" src="<?=ag_h($url)?>" alt="<?=ag_h($name)?>"><span>View artwork ↗</span></button><div class="card-meta"><span class="step"><?=$uploaded?'MY UPLOADS':'BUILT-IN ARTWORK'?></span><?php if($selected):?><span class="active-badge">SELECTED</span><?php endif ?></div><h3><?=ag_h($name)?></h3><?php if($selected):?><p class="small-note"><?=ag_h(implode(', ',$selected))?></p><?php endif ?><form method="post"><?php $hidden('artwork_apply')?><input type="hidden" name="<?=$uploaded?'upload':'artwork'?>" value="<?=ag_h($id)?>"><div class="art-actions"><?php foreach(array('public'=>'Apply to Public','admin'=>'Apply to Admin','user'=>'Apply to User','current-theme'=>'Apply to current theme') as $scope=>$label):?><button name="target" value="<?=$scope?>" class="<?=$scope==='current-theme'?'quiet':'secondary'?>"><?=$label?></button><?php endforeach ?></div></form></article><?php };?>
<section class="library-section" data-library="builtins"><div class="library-heading"><h2>Built-in artwork</h2><span>14 original backgrounds · portable PNG · protected</span></div><div class="art-grid"><?php foreach(ag_sd_artwork_library() as $id=>$art)$artCard($id,$art['url'],$art['name']);?></div></section>
<section class="library-section" data-library="uploads"><div class="library-heading"><h2>My uploads</h2><span>User files · retained for history and restore</span></div><form method="post" enctype="multipart/form-data" class="upload-drop studio-panel"><?php $hidden('artwork_upload')?><label>Add your artwork<input type="file" name="artworkUpload" accept="image/png,image/jpeg,image/gif,image/webp" required></label><button>Add to My uploads</button><p class="small-note">PNG, JPG, GIF or WebP, up to 8 MB. Uploading does not apply it.</p></form><div class="art-grid"><?php $uploads=glob(ag_sd_asset_dir().'/*') ?: array();foreach($uploads as $index=>$file){$name=basename($file);$artCard($name,ag_sd_asset_url($name),'Custom artwork '.($index+1),true);}if(!$uploads):?><div class="empty-state"><span>◇</span><h3>Your library starts here</h3><p>Add a logo, landscape or background to make a design your own.</p></div><?php endif ?></div></section>
<section class="studio-panel reset-artwork"><h2>Restore a clean background</h2><p>This clears the selected custom background. Previous settings and uploaded files remain available in history.</p><form method="post"><?php $hidden('artwork_apply')?><label>Area<select name="target"><?php foreach(ag_sd_scopes() as $id=>$label):?><option value="<?=$id?>"><?=ag_h($label)?></option><?php endforeach ?><option value="current-theme">Current Public theme and matching areas</option></select></label><button class="secondary">Remove custom artwork / restore default</button></form></section><details class="studio-panel"><summary>Existing picture slots and display settings</summary><p>Your original picture slots remain available.</p><a class="button secondary" href="/Other/admin-site-design-artwork.php">Manage pictures &amp; display settings →</a></details>
